INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Weighted_Pull_Ups', 'Weighted Pull Ups', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'intermediate', 'Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip. You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position. Now, exhale and pull your torso up until your head is abo'),
('Weighted_Sissy_Squat', 'Weighted Sissy Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position. As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second. After your one '),
('Weighted_Sit-Ups_-_With_Bands', 'Weighted Sit-Ups - With Bands', 'core', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them. Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain sta'),
('Weighted_Squat', 'Weighted Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'strength', 'intermediate', 'Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out. Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position. Begin by bending the knees as you maintain a straight posture with the head up. C'),
('Wide-Grip_Barbell_Bench_Press', 'Wide-Grip Barbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. After a second pause, bring the bar back to the starting position as you breathe'),
('Wide-Grip_Decline_Barbell_Bench_Press', 'Wide-Grip Decline Barbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your lower chest. After a second pause, bring the bar back to the st'),
('Wide-Grip_Decline_Barbell_Pullover', 'Wide-Grip Decline Barbell Pullover', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms. When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position. Begin by moving the barbell back down in a semicircular motion as if you were goi'),
('Wide-Grip_Lat_Pulldown', 'Wide-Grip Lat Pulldown', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your sho'),
('Wide-Grip_Pulldown_Behind_The_Neck', 'Wide-Grip Pulldown Behind The Neck', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'intermediate', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to you'),
('Wide-Grip_Rear_Pull-Up', 'Wide-Grip Rear Pull-Up', 'back', ARRAY['arms','back','shoulders']::text[], 'bodyweight', 'strength', 'intermediate', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position. Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. '),
('Wide-Grip_Standing_Barbell_Curl', 'Wide-Grip Standing Barbell Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second an'),
('Wide_Stance_Barbell_Squat', 'Wide Stance Barbell Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a w'),
('Wide_Stance_Stiff_Legs', 'Wide Stance Stiff Legs', 'legs', ARRAY['legs','legs','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position. Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, '),
('Wind_Sprints', 'Wind Sprints', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position. Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3 Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible. Continue alternating between legs until the set is complete.'),
('Windmills', 'Windmills', 'legs', ARRAY['legs','legs','back']::text[], 'other', 'stretching', 'intermediate', 'Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position. Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand. Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions.'),
('Worlds_Greatest_Stretch', 'World''s Greatest Stretch', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'stretching', 'intermediate', 'This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds. Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the '),
('Wrist_Circles', 'Wrist Circles', 'arms', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Start by standing straight with your feet being shoulder width apart from each other. Elevate your arms to the side of you until they are fully extended and parallel to the floor at a height that is evenly aligned with your shoulders. Tip: Your torso and arms should form the letter "T: Your palms should be facing down. This is the starting position. Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion. Tip: Pretend that you are tryin'),
('Wrist_Roller', 'Wrist Roller', 'arms', ARRAY['shoulders']::text[], 'other', 'strength', 'beginner', 'To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart. Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position. Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the rol'),
('Wrist_Rotations_with_Straight_Bar', 'Wrist Rotations with Straight Bar', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position. Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure. Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.'),
('Yoke_Walk', 'Yoke Walk', 'legs', ARRAY['core','legs','legs','legs','legs','legs','back']::text[], 'other', 'strongman', 'intermediate', 'The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects. Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels. Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet.'),
('Zercher_Squats', 'Zercher Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm. Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you '),
('Zottman_Curl', 'Zottman Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Make sure the palms of the hands are facing each other. This will be your starting position. While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the d'),
('Zottman_Preacher_Curl', 'Zottman Preacher Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position. As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched. Now rotate your wrists once you are at the bottom of the movement so that th')
